// Input: items[0].json.text (string) มาจาก AI agent
// Output: items[0].json.messages (array of { type: "text", text: string })

function sanitizeForLine(raw) {
  // 1) Normalize Unicode (NFC) – ช่วยให้สม่ำเสมอเรื่องสระ/วรรณยุกต์
  const normalized = raw.normalize('NFC');

  // 2) Strip control chars ยกเว้น \n \t (กันอักขระซ่อน)
  const noControls = normalized.replace(
    // U+0000 - U+001F และ U+007F ยกเว้น \n(0x0A), \t(0x09)
    /[\u0000-\u0008\u000B-\u000C\u000E-\u001F\u007F]/g,
    ''
  );

  // 3) Remove/flatten markup ที่ LINE ไม่รองรับ (Markdown/HTML พื้นฐาน)
  //   - เอา ```code``` ออก
  let text = noControls.replace(/```[\s\S]*?```/g, (m) => {
    const inner = m.replace(/```/g, '').trim();
    return inner ? `\n${inner}\n` : '';
  });
  //   - เอา inline `code` ออก (คงข้อความไว้)
  text = text.replace(/`([^`]+)`/g, '$1');
  //   - ตัดแท็ก HTML เบื้องต้น
  text = text.replace(/<\/?[^>]+>/g, '');

  // 4) Normalize whitespace: ตัดช่องว่างหัวท้าย, บีบหลายบรรทัดที่ว่างเปล่า
  text = text.trim().replace(/\n{3,}/g, '\n\n');

  // 5) ป้องกันข้อความ “รันยาวไร้ช่องไฟ” – คั่นระหว่างหัวข้อ/bullet
  //    (ตัวอย่าง: แปลง "- " ให้เป็น bullet มาตรฐาน)
  text = text.replace(/^\s*-\s+/gm, '• ');

  return text;
}

// ตัดข้อความแบบ “Grapheme-aware” ด้วย Intl.Segmenter (กัน emoji แตก)
function splitGraphemes(str) {
  if (typeof Intl !== 'undefined' && Intl.Segmenter) {
    const seg = new Intl.Segmenter('th', { granularity: 'grapheme' });
    return Array.from(seg.segment(str), s => s.segment);
  }
  // fallback (อาจทำ emoji แตกได้ในบางกรณี)
  return Array.from(str);
}

// กำหนดเพดานความยาวต่อข้อความ (อย่าใช้ตัวเลขเป๊ะหากไม่แน่ใจ policy ปัจจุบันของ LINE)
// เลือก conservative เผื่อ margin ให้ safe
const MAX_PER_MESSAGE = 1800;

function chunkForLine(text) {
  const g = splitGraphemes(text);
  const chunks = [];
  let buf = [];
  let len = 0;

  for (const ch of g) {
    // นับตามจำนวน grapheme (หยาบๆ)
    if (len + ch.length > MAX_PER_MESSAGE) {
      chunks.push(buf.join(''));
      buf = [ch];
      len = ch.length;
    } else {
      buf.push(ch);
      len += ch.length;
    }
  }
  if (buf.length) chunks.push(buf.join(''));

  return chunks;
}

// --- main ---
const raw = ($input.first().json.output ?? '').toString();
const cleaned = sanitizeForLine(raw);

// ถ้าต้องการ post-process เพิ่ม เช่น mapping คำเตือน/URL/แทน emoji reserved
// ทำในขั้นตอนนี้ได้

const parts = chunkForLine(cleaned);

// ประกอบเป็น payload แบบ LINE Messaging API (type=text)
const messages = parts.map(p => ({ type: 'text', text: p }));

return [{ json: { messages } }];
